// Contract test between the Go event producer and this frontend.
//
// The fixtures in ../spec/agent-events.json are generated by the Go test
// TestAgentEventFixturesUpToDate (internal/agent/tool_event_contract_test.go)
// from the real payload builders, so each entry's `data` is exactly what the
// server puts on the wire. Each entry's `expect` lists what
// normalizeToolActivity() must recover from that payload, using frontend
// field names and frontend-normalized values.
//
// If the Go side renames a key or changes a value shape, regenerating the
// fixtures makes this test fail until the frontend understands the new
// payload; if the frontend loses the ability to read an existing key, this
// test fails without any Go change. Regenerate after intentional changes:
//
//   AUTOTO_UPDATE_EVENT_FIXTURES=1 go test ./internal/agent -run TestAgentEventFixturesUpToDate

import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import { normalizeToolActivity, renderToolActivityCardHTML } from "./chat-rendering.mjs";

const fixtureFile = JSON.parse(readFileSync(new URL("../spec/agent-events.json", import.meta.url), "utf8"));

test("agent event fixtures are present and well-formed", () => {
  assert.ok(Array.isArray(fixtureFile.fixtures) && fixtureFile.fixtures.length >= 5, "fixture file must contain the tool lifecycle fixtures");
  for (const fixture of fixtureFile.fixtures) {
    assert.ok(fixture.name, "fixture needs a name");
    assert.ok(["tool.started", "tool.finished", "tool.approval_required"].includes(fixture.eventType), `${fixture.name}: unknown event type ${fixture.eventType}`);
    assert.ok(fixture.data && typeof fixture.data === "object", `${fixture.name}: missing data`);
    assert.ok(fixture.expect && typeof fixture.expect === "object", `${fixture.name}: missing expect`);
  }
});

for (const fixture of fixtureFile.fixtures) {
  test(`contract: ${fixture.name}`, () => {
    // Live events reach the renderer as records whose `data` carries the
    // payload, which is exactly how normalizeToolActivity merges them.
    const normalized = normalizeToolActivity({ data: fixture.data });
    for (const [field, expected] of Object.entries(fixture.expect)) {
      assert.deepEqual(
        normalized[field],
        expected,
        `${fixture.name}: normalizeToolActivity().${field} no longer matches the Go payload contract`,
      );
    }
  });

  test(`renders without loss: ${fixture.name}`, () => {
    const html = renderToolActivityCardHTML({ data: fixture.data });
    assert.ok(typeof html === "string" && html.length > 0, `${fixture.name}: card render produced no output`);
    assert.ok(html.includes(fixture.expect.toolName), `${fixture.name}: card render dropped the tool name`);
  });
}
